            float v00 = vscb_it[TQ_PROW(p0c) * nkv];
            float v01 = vscb_it[TQ_PROW(p0c + 1) * nkv];
            float v10 = vscb_it[TQ_PROW(p1c) * nkv];
            float v11 = vscb_it[TQ_PROW(p1c + 1) * nkv];
