            float a2_lo = alph[16 + gr], a2_hi = alph[24 + gr];
            #pragma unroll
            for (int f = 0; f < 4; f++) { oacc2[f][0] *= a2_lo; oacc2[f][1] *= a2_lo; oacc2[f][2] *= a2_hi; oacc2[f][3] *= a2_hi; }
