                const uint32_t c8 = tq_t4_vbits(vcb8 + q8 * cstride4, z8, cb), c9 = tq_t4_vbits(vcb8 + q9 * cstride4, z9, cb);
                const float v0 = tq_t4_scale(z0), v1 = tq_t4_scale(z1), v8 = tq_t4_scale(z8), v9 = tq_t4_scale(z9);
                #pragma unroll
                for (int f = 0; f < 4; f++) {
