                    if (rp - t0 < t4nenc) {
                        const size_t q = TQ_PROW(rp);
                        const uint32_t z = tq_t4_side(t4p.vside, q, nkv, kv_head);
                        const uint32_t c = tq_t4_vbits(vcb8 + q * cstride4, z, cb);
                        const float vs = tq_t4_scale(z);
