                    uint32_t b1 = tq_pack_bf16(v[2][f], v[3][f]);
                    tq_mma_bf16_m16n8k16(oacc[f], a, b0, b1);
                    if constexpr (QT == 2) tq_mma_bf16_m16n8k16(oacc2[f], a2, b0, b1);
                }
